"""Climate reading (Macro Clima), verification step 2: macro/core.js against reference implementations, on the 13
reference weather files. Writes verification.md.
- Sun position: pvlib, NREL SPA, apparent elevation (with refraction, as the app), at the middle of each hour.
- Sun on walls and roof: pvlib Perez 1990 with the app's sun, albedo 0.2.
- Psychrometrics: psychrolib (SI): saturation pressure, humidity ratio, wet bulb, enthalpy, dew point; 2,000 random states.
- UTCI: pythermalcomfort utci; 2,000 random conditions.
- Adaptive comfort, EN 16798-1: running mean of outdoor temperature (alpha 0.8) and the category II band, against
  pythermalcomfort running_mean_outdoor_temperature and adaptive_en."""
import json, os, sys, numpy as np, pandas as pd, pvlib, psychrolib as P
from pythermalcomfort.models import utci as ptc_utci, adaptive_en
from pythermalcomfort.utilities import running_mean_outdoor_temperature
P.SetUnitSystem(P.SI)
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "lib"))
from paths import WORK
HERE = os.path.dirname(os.path.abspath(__file__)); R = json.load(open(os.path.join(WORK, "macro", "verify.json")))
md = ["# Macro Clima: code verification", "", "Generated by `verify.py`.", "", "## Sun and sun on surfaces (pvlib)", "",
      "| File | Elevation, bias / largest | Azimuth above 5°, RMS | Annual sun on N / E / S / W / roof, difference | Hourly RMS, largest surface |", "|---|---|---|---|---|"]
for f, d in R["files"].items():
    import datetime as _dt
    tz = d["tz"]; times = pd.date_range("2023-01-01 00:30", periods=8760, freq="h", tz=_dt.timezone(_dt.timedelta(hours=tz)))
    sp = pvlib.solarposition.get_solarposition(times, d["lat"], d["lon"], method="nrel_numpy")
    el, az = np.array(d["alt"]), np.array(d["az"]); rel, raz = 90 - sp["apparent_zenith"].to_numpy(), sp["azimuth"].to_numpy()   # the app includes refraction
    m = (rel > 0) | (el > 0); m2 = rel > 5; de = el[m] - rel[m]; da = ((az[m2] - raz[m2] + 540) % 360) - 180
    dni = np.where(el > 0, np.array(d["dni"]), 0.0); dhi, ghi = np.array(d["dhi"]), np.array(d["ghi"])
    extra = pvlib.irradiance.get_extra_radiation(times).to_numpy(); am = pvlib.atmosphere.get_relative_airmass(90 - el)
    dif, rms = [], []
    for k, arr in d["walls"].items():
        tilt, saz = map(float, k.split("_"))
        ref = np.nan_to_num(np.asarray(pvlib.irradiance.get_total_irradiance(tilt, saz, 90 - el, az, dni, ghi, dhi, dni_extra=extra, airmass=am, albedo=0.2, model="perez")["poa_global"], dtype=float))
        mine = np.array(arr); dif.append(100 * (mine.sum() / ref.sum() - 1)); rms.append(np.sqrt(np.mean((mine - ref) ** 2)))
    md.append(f"| {f.replace('.epw', '')} | {de.mean():+.2f}° / {np.abs(de).max():.2f}° | {np.sqrt((da ** 2).mean()):.2f}° | {' / '.join(f'{x:+.2f}%' for x in dif)} | {max(rms):.1f} W/m² |")
A = np.array(R["psy"]); e = {"saturation pressure": [], "humidity ratio": [], "wet bulb": [], "enthalpy": [], "dew point": []}
for t, rh, p, pws, w, wb, h, dp in A:
    e["saturation pressure"].append(abs(pws / P.GetSatVapPres(t) - 1)); e["humidity ratio"].append(abs(w / P.GetHumRatioFromRelHum(t, rh / 100, p) - 1))
    e["wet bulb"].append(abs(wb - P.GetTWetBulbFromHumRatio(t, w, p))); e["enthalpy"].append(abs(h / (P.GetMoistAirEnthalpy(t, w) / 1000) - 1)); e["dew point"].append(abs(dp - P.GetTDewPointFromHumRatio(t, w, p)))
md += ["", "## Psychrometrics (psychrolib)", "", "2,000 random states (−30 to 45 °C, 5 to 100 % humidity, 800 to 1,050 hPa), largest difference:", ""]
md += [f"- {k}: {max(v) * (100 if k in ('saturation pressure', 'humidity ratio', 'enthalpy') else 1):.3g}{' %' if k in ('saturation pressure', 'humidity ratio', 'enthalpy') else ' K'}" for k, v in e.items()]
U = np.array(R["utci"]); ok = ~np.isnan(U[:, 4]); ref = ptc_utci(tdb=U[ok, 0], tr=U[ok, 1], v=U[ok, 2], rh=U[ok, 3], limit_inputs=False, round_output=False)
ref = np.asarray(ref.utci if hasattr(ref, "utci") else ref["utci"], dtype=float)
md += ["", "## UTCI (pythermalcomfort)", "", f"{ok.sum()} conditions inside the polynomial's range: largest difference {np.nanmax(np.abs(U[ok, 4] - ref)):.2e} K."]
rm_err, band_err, rm_exact = [], [], []
for f, d in R["files"].items():
    dm = np.array(d["dm"]); rm = np.array(d["rmEN"])
    ref_rm = [running_mean_outdoor_temperature(list(np.concatenate([dm, dm])[365 + k - 7:365 + k][::-1]), alpha=0.8, units="SI") for k in range(365)]
    rm_err.append(np.abs(rm - np.array(ref_rm)).max())
    ex = np.zeros(365); r_ = dm.mean()   # independent exponential running mean, EN 16798-1 eq. B.2, two passes over the year as the app
    for _ in range(2):
        for k in range(365): r_ = 0.2 * dm[(k - 1) % 365] + 0.8 * r_; ex[k] = r_
    rm_exact.append(np.abs(rm - ex).max())
    v = np.array(d["enValid"]) > 0; v15 = v & (rm >= 15)   # EN 16798-1: the lower limit applies from a running mean of 15 °C
    r = adaptive_en(tdb=np.full(365, 25.0), tr=np.full(365, 25.0), t_running_mean=rm, v=np.full(365, 0.1), limit_inputs=False, round_output=False)
    hi = np.asarray(r.tmp_cmf_cat_ii_up if hasattr(r, "tmp_cmf_cat_ii_up") else r["tmp_cmf_cat_ii_up"], dtype=float); lo = np.asarray(r.tmp_cmf_cat_ii_low if hasattr(r, "tmp_cmf_cat_ii_low") else r["tmp_cmf_cat_ii_low"], dtype=float)
    band_err.append(max(np.abs(np.array(d["enHi"])[v] - hi[v]).max(), np.abs(np.array(d["enLo"])[v15] - lo[v15]).max()))
md += ["", "## Adaptive comfort, EN 16798-1 (pythermalcomfort)", "",
       f"- Running mean outdoor temperature (alpha 0.8): the app runs the exponential mean of EN 16798-1 over the year (two passes, so 1 January follows 31 December). An independent implementation of that form agrees within {max(rm_exact):.1e} K. pythermalcomfort uses the 7-day approximation of the standard; the two forms differ by up to {max(rm_err):.2f} K on single days.",
       f"- Category II band from the same running mean (upper limit for a running mean of 10 to 30 °C, lower limit from 15 °C, below which the app holds it at its 15 °C value): largest difference {max(band_err):.1e} K."]
open(os.path.join(HERE, "verification.md"), "w").write("\n".join(md) + "\n"); print("\n".join(md))
